(function () {
    function startPortfolioIntro() {
        const loader = document.getElementById('intro-loader');
        if (!loader || loader.dataset.p26Started === '1') return;
        loader.dataset.p26Started = '1';

        const bar = loader.querySelector('.intro-progress-bar');
        const counter = loader.querySelector('.intro-counter');
        document.body.classList.add('intro-active');

        let progress = 0;
        let finished = false;
        const interval = window.setInterval(function () {
            progress = Math.min(100, progress + Math.max(2, (100 - progress) * 0.08));
            if (bar) bar.style.width = progress + '%';
            if (counter) counter.textContent = Math.floor(progress) + '%';
            if (progress >= 100) {
                window.clearInterval(interval);
                window.setTimeout(finishIntro, 350);
            }
        }, 60);

        function finishIntro() {
            if (finished) return;
            finished = true;
            loader.classList.add('done');
            document.body.classList.remove('intro-active');

            const nav = document.getElementById('mainNav');
            if (nav) nav.classList.add('active');
            const heroImage = document.getElementById('teamImage');
            if (heroImage) heroImage.classList.add('visible');
            document.querySelectorAll('.hero-title, .hero-subtitle, .hero-desc, .hero-buttons')
                .forEach(function (element) { element.classList.add('visible'); });

            if (window.AOS && typeof window.AOS.refresh === 'function') {
                window.setTimeout(function () { window.AOS.refresh(); }, 400);
            }
            window.setTimeout(function () { if (loader.parentNode) loader.remove(); }, 1200);
        }

        // Failsafe if a third-party script delays the progress animation.
        window.setTimeout(finishIntro, 7000);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', startPortfolioIntro, { once: true });
    } else {
        startPortfolioIntro();
    }
